/** New one-parcel/one-THK contract; no RPK callback compatibility fixtures. */
class RefundParcelsTest {
    RefundReturnTest f;RefundParcels parcels;RefundReturnService returns;SharedRefundDocuments shared;HttpServer server;
    String allocationMode="STRICT";boolean partialAllowed=false,uniformCost=false;RefundReceiptAllocator allocator;RefundAllocationClient allocationOrders;
    Map<String,Object> allocationContext(){List<Map<String,Object>> priorities=new ArrayList<>();for(long plan=1;plan<=10;plan++)priorities.add(map("plan_id",plan,"refund_id",plan+20,"eligible",true,"refund_created","2026-10-01 00:00:00","priority_basis","PLATFORM_CREATED"));return map("policy",map("revision",3,"allocation_mode",allocationMode,"allow_partial_allocation",partialAllowed?1:0,"allocation_order","REFUND_CREATED"),"priorities",priorities);}
    AtomicInteger creates=new AtomicInteger(),logs=new AtomicInteger(100);String lastCreate="";
    @BeforeEach void setup() throws Exception {
        f=new RefundReturnTest();f.setup();for(String table:Arrays.asList("wms_refund_parcel_document","wms_refund_parcel_receipt","wms_refund_parcel_member","wms_refund_parcel","wms_refund_return","wms_simulation_store_info","owner_warehouse","owner_info","wms_real_store_info","wms_connection"))f.f.jdbc.update("DELETE FROM "+table);
        parcels=new RefundParcels();parcels.db=f.f.db;parcels.connections=mock(WmsConnections.class);parcels.protocol=f.f.protocol;parcels.logs=mock(WmsInteractionLog.class);when(parcels.logs.start(anyString(),anyLong(),isNull(),anyString(),anyString(),anyString(),anyString())).thenAnswer(x->(long)logs.incrementAndGet());
        allocator=new RefundReceiptAllocator();allocator.db=f.f.db;allocationOrders=mock(RefundAllocationClient.class);allocator.orders=allocationOrders;parcels.allocator=allocator;when(allocationOrders.context(anyString(),anyLong(),anyList(),anyString())).thenAnswer(x->com.ruoyi.common.core.domain.R.ok(allocationContext()));
        shared=new SharedRefundDocuments();ReflectionTestUtils.setField(shared,"carrierBridge",com.oms.supplychain.CarrierFixture.bridge());shared.db=f.f.db;shared.connections=parcels.connections;shared.protocol=f.f.protocol;shared.logs=parcels.logs;parcels.shared=shared;returns=f.service;ReflectionTestUtils.setField(returns,"parcels",parcels);ReflectionTestUtils.setField(returns,"shared",shared);ReflectionTestUtils.setField(returns,"connections",parcels.connections);
        server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{String body=org.springframework.util.StreamUtils.copyToString(e.getRequestBody(),StandardCharsets.UTF_8);String sn=QimenReturnProtocol.documentSn(body);if(sn.isEmpty()){String start="<orderCode>";sn=body.substring(body.indexOf(start)+start.length(),body.indexOf("</orderCode>"));}if(e.getRequestURI().getQuery().contains("returnorder.create")){creates.incrementAndGet();lastCreate=body;}String response="<response><flag>success</flag><returnOrder><returnOrderCode>"+sn+"</returnOrderCode><returnOrderId>WH_SHARED</returnOrderId><warehouseCode>EXT-W</warehouseCode><ownerCode>EXT-O</ownerCode><status>ACCEPT</status></returnOrder></response>";byte[] bytes=response.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();
        Map<String,Object> connection=map("id",1,"provider","QIMEN","api_version","2.0","app_key","app","customer_id","customer","endpoint","http://127.0.0.1:"+server.getAddress().getPort()+"/","shared_return_waybill",0,"enabled",1);when(parcels.connections.usable(anyString(),anyLong())).thenReturn(connection);when(parcels.connections.get(anyString(),anyLong())).thenReturn(connection);when(parcels.connections.secret(anyMap())).thenReturn("fixture");
        long o=f.f.db.insert("owner_info",map("company_code","QM","owner_code","O","owner_name","owner","is_sync",1,"is_enable",2));long w=f.f.db.insert("wms_real_store_info",map("company_code","qm","real_store_code","W","wms_name","warehouse","wms_type",1,"status",2));long rel=f.f.db.insert("owner_warehouse",map("company_code","QM","owner_id",o,"real_store_id",w,"status",2));f.f.db.insert("wms_simulation_store_info",map("company_code","QM","wms_simulation_code","V1","wms_simulation_name","V1","status",2,"owner_warehouse_id",rel,"connection_id",1,"external_owner","EXT-O","external_warehouse","EXT-W"));f.f.db.insert("wms_connection",map("id",1,"company_code","QM","name","fixture","provider","QIMEN","api_version","2.0","environment","TEST","endpoint",connection.get("endpoint"),"app_key","app","customer_id","customer","secret_cipher","fixture","callback_key","callback","enabled",1));
    }
    @AfterEach void stop(){if(server!=null)server.stop(0);}
    Map<String,Object> policy(){return map("enabled",1,"manual_enabled",1,"auto_enabled",1,"scope","SAME_ORDER","max_refunds",100,"max_quantity",0,"collect_seconds",120,"store_codes",Arrays.asList("V1"));}
    Map<String,Object> input(long plan,long join){long qty=plan==1?2:1;Map<String,Object> command=map("refund_id",plan+20,"refund_sn","TK_"+plan,"order_sn","SO_TEST","platform_tid","123456","store_code","V1","sku_sn","A","goods_name","item","quantity",qty,"return_basis",map("original_shipment_sn","XS_TEST","unit_cost",uniformCost||plan==1?"2.50":"4.50","owner_code","O"),"sender",Collections.emptyMap(),"return_address","same verified return address","return_contact","warehouse desk");return map("policy",policy(),"channel_id",1,"platform_tid","123456","association_mode","MANUAL","refund_id",plan+20,"refund_sn","TK_"+plan,"order_sn","SO_TEST","source_line_id",66,"sku_sn","A","quantity",qty,"store_code","V1","carrier_code","SF","waybill","SHARED_WAYBILL","actor","test","reason","same parcel verified","evidence","manifest","confirmed",true,"join_parcel_id",join,"request_json",command,"return_address",command.get("return_address"),"return_contact",command.get("return_contact"));}
    long attach(long plan,long join){return id(parcels.attach("QM",plan,input(plan,join)).get("id"));}
    long group(){long p=attach(1,0);attach(2,p);attach(3,p);return p;}
    @Test void readOnlyParcelProjectionPreservesConfirmedLogisticsAndConnectionEnvironment(){long p=group();Map<String,Object> row=parcels.list("QM",21).get(0);assertEquals(p,id(row.get("id")));assertEquals("SHARED_WAYBILL",row.get("waybill"));assertEquals("TEST",row.get("warehouse_environment"));assertEquals(3,((List<?>)row.get("members")).size());assertEquals(0,creates.get());assertNull(row.get("warehouse_document"));assertTrue(parcels.list("OTHER",21).isEmpty());}
    long version(long p){return id(f.f.db.one("SELECT control_version FROM wms_refund_parcel WHERE id=?",p).get("control_version"));}
    void dispatch(long p){returns.prepare("QM",1,map("parcel_version",version(p)));assertEquals("ACCEPTED",shared.document("QM",p).get("dispatch_state"));}
    String body(long p,String message,int qty,String line,boolean complete){return "<request><returnOrder><returnOrderCode>"+shared.document("QM",p).get("return_sn")+"</returnOrderCode><returnOrderId>WH_SHARED</returnOrderId><warehouseCode>EXT-W</warehouseCode><ownerCode>EXT-O</ownerCode><outBizCode>"+message+"</outBizCode><orderType>THRK</orderType><confirmType>"+(complete?0:1)+"</confirmType></returnOrder><orderLines><orderLine><orderLineNo>"+line+"</orderLineNo><itemCode>A</itemCode><ownerCode>EXT-O</ownerCode><actualQty>"+qty+"</actualQty><inventoryType>ZP</inventoryType><batchCode>RETURN_BATCH</batchCode></orderLine></orderLines></request>";}
    String receive(String body){return returns.callback("QM","callback",f.f.params(body),body);}
    long task(long plan){return id(f.f.db.one("SELECT id FROM wms_refund_return WHERE plan_id=? ORDER BY generation DESC LIMIT 1",plan).get("id"));}
    String line(long plan){return text(f.f.db.one("SELECT id FROM wms_refund_parcel_member WHERE plan_id=? AND active=1",plan).get("id"));}
    long event(String message){return id(f.f.db.one("SELECT id FROM wms_refund_parcel_receipt WHERE message_id=?",message).get("id"));}
    Map<String,Object> decision(long p){return map("decision","ALLOCATE","confirmed",true,"actor","test","reason","physical sources verified","evidence","warehouse manifest","allocations",Arrays.asList(map("line_index",0,"task_id",task(1),"good_qty",2,"bad_qty",0),map("line_index",0,"task_id",task(2),"good_qty",1,"bad_qty",0)));}
    long posted(){return f.f.jdbc.queryForObject("SELECT COALESCE(SUM(posted_quantity),0) FROM wms_refund_return",Long.class);}
    @Test void threeRefundsCreateOneThkOneWarehouseRequestAndThreeSourceLines(){long p=group();dispatch(p);assertEquals(1,creates.get());assertEquals(1L,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_document",Long.class));assertEquals(3L,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_return WHERE return_sn LIKE 'RSL%' AND ticket_id IS NULL",Long.class));assertEquals(3,lastCreate.split("<orderLine>",-1).length-1);String sn=text(shared.document("QM",p).get("return_sn"));for(int i=1;i<=3;i++)assertEquals(sn,returns.detail("QM",i).get("return_sn"));assertEquals(3L,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_tickets_goods WHERE sn=?",Long.class,sn));}
    @Test void repeatedDispatchNeverCreatesAnotherThk(){long p=group();dispatch(p);dispatch(p);assertEquals(1,creates.get());}
    @Test void lineReceiptPostsOnlyItsRefundAndOriginalCostOnce(){long p=group();dispatch(p);String b=body(p,"LINE",1,line(3),false);assertTrue(receive(b).contains("success"));assertTrue(receive(b).contains("success"));assertEquals(1,posted());assertEquals(0,id(returns.detail("QM",1).get("posted_quantity")));assertEquals(1,id(returns.detail("QM",3).get("posted_quantity")));verify(f.f.inventory,times(1)).addInventory(any(),eq("QM"));}
    @Test void ambiguousPartialSkuReceiptWaitsAndExplicitAllocationPostsExactlyOnce(){long p=group();dispatch(p);String b=body(p,"GROUP",3,"",false);assertTrue(receive(b).contains("success"));assertEquals(0,posted());parcels.allocate("QM",21,p,event("GROUP"),decision(p),returns);assertEquals(3,posted());assertTrue(receive(b).contains("success"));assertEquals(3,posted());assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",21,p,event("GROUP"),decision(p),returns));verify(f.f.inventory,times(2)).addInventory(any(),eq("QM"));}
    @Test void lastRemainingSkuReceiptCanAutomaticallyResolve(){long p=group();dispatch(p);receive(body(p,"FIRST",3,"",false));parcels.allocate("QM",21,p,event("FIRST"),decision(p),returns);assertTrue(receive(body(p,"LAST",1,"",true)).contains("success"));assertEquals(4,posted());assertEquals("COMPLETED",returns.detail("QM",3).get("receipt_state"));}
    @Test void fullSameGradeSkuReceiptClosesAllKnownSourcesWithoutArbitraryShortageAllocation(){long p=group();dispatch(p);assertTrue(receive(body(p,"ALL",4,"",true)).contains("success"));assertEquals(4,posted());for(int plan=1;plan<=3;plan++)assertEquals("COMPLETED",returns.detail("QM",plan).get("receipt_state"));verify(f.f.inventory,times(3)).addInventory(any(),eq("QM"));}
    @Test void conflictingDuplicateCannotChangeStock(){long p=group();dispatch(p);receive(body(p,"SAME",1,line(1),false));assertTrue(receive(body(p,"SAME",2,line(1),false)).contains("failure"));assertEquals(1,posted());}
    @Test void wrongSignatureOwnerWarehouseOrExternalOrderCannotCreateReceipt(){long p=group();dispatch(p);String b=body(p,"BAD",1,line(1),false);Map<String,String> params=f.f.params(b);params.put("sign","wrong");assertTrue(returns.callback("QM","callback",params,b).contains("failure"));for(String bad:Arrays.asList(b.replace("EXT-W","OTHER"),b.replace("EXT-O","OTHER"),b.replace("WH_SHARED","OTHER")))assertTrue(receive(bad).contains("failure"));assertEquals(0,eventCount());}
    long eventCount(){return f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_receipt",Long.class);}
    @Test void rpkIsNotAWarehouseReturnDocument(){long p=group();dispatch(p);String b=body(p,"RPK",1,"",false).replace(text(shared.document("QM",p).get("return_sn")),text(f.f.db.one("SELECT parcel_sn FROM wms_refund_parcel WHERE id=?",p).get("parcel_sn")));assertTrue(receive(b).contains("failure"));assertEquals(0,eventCount());}
    @Test void finalShortAndOverReceiptNeverAutoPost(){long p=group();dispatch(p);receive(body(p,"SHORT",1,line(1),true));receive(body(p,"OVER",3,line(1),false));assertEquals(0,posted());assertEquals(2L,eventCount());}
    @Test void differentAddressOrContactCannotMerge(){long p=attach(1,0);Map<String,Object> i=input(2,p);i.put("return_address","different");Map<String,Object> wrongAddress=i;assertThrows(IllegalArgumentException.class,()->parcels.attach("QM",2,wrongAddress));i=input(2,p);i.put("return_contact","different");Map<String,Object> wrong=i;assertThrows(IllegalArgumentException.class,()->parcels.attach("QM",2,wrong));}
    @Test void matchingWaybillRequiresExplicitJoinAndSameShopOrder(){long p=attach(1,0);assertThrows(IllegalArgumentException.class,()->attach(2,0));Map<String,Object> i=input(2,p);i.put("channel_id",2);assertThrows(IllegalArgumentException.class,()->parcels.attach("QM",2,i));}
    @Test void shopAndQuantityLimitsAreEnforced(){long p=attach(1,0);Map<String,Object> i=input(2,p);Map<String,Object> rules=policy();rules.put("max_refunds",1);i.put("policy",rules);assertThrows(IllegalArgumentException.class,()->parcels.attach("QM",2,i));}
    @Test void frozenThkRejectsAppendAndLateSupplementRegardlessOfOldFlags(){long p=group();dispatch(p);assertThrows(IllegalArgumentException.class,()->attach(4,p));Map<String,Object> i=input(4,p);i.put("late_review",true);assertThrows(IllegalArgumentException.class,()->parcels.attach("QM",4,i));assertEquals(1,creates.get());}
    @Test void stoppingOneSourceBeforeDispatchRemovesItFromForecast(){long p=group();parcels.detach("QM",23,3);dispatch(p);assertEquals(3,id(shared.document("QM",p).get("quantity")));assertEquals(2,lastCreate.split("<orderLine>",-1).length-1);}
    @Test void detachAfterDispatchCannotCancelOtherRefunds(){long p=group();dispatch(p);assertThrows(IllegalArgumentException.class,()->parcels.detach("QM",23,3));assertEquals("NONE",shared.document("QM",p).get("cancel_state"));}
    @Test void wholeDocumentCancellationRequiresCurrentScopeConfirmation(){long p=group();dispatch(p);Map<String,Object> input=map("reason","stop","evidence","proof","confirmed_shared",true,"parcel_version",version(p)-1);assertThrows(IllegalArgumentException.class,()->shared.action("QM",1,"cancel",input,returns));input.put("parcel_version",version(p));shared.action("QM",1,"cancel",input,returns);assertEquals("CONFIRMED",shared.document("QM",p).get("cancel_state"));assertEquals(3L,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_return WHERE cancel_state='CONFIRMED'",Long.class));}
    @Test void canceledThkLateReceiptWaitsUntilHumanConfirms(){long p=group();dispatch(p);shared.action("QM",1,"cancel",map("reason","stop","evidence","proof","confirmed_shared",true,"parcel_version",version(p)),returns);assertTrue(receive(body(p,"LATE",1,line(3),false)).contains("success"));assertEquals(0,posted());Map<String,Object> d=decision(p);d.put("allocations",Arrays.asList(map("line_index",0,"task_id",task(3),"good_qty",1,"bad_qty",0)));parcels.allocate("QM",23,p,event("LATE"),d,returns);assertEquals(1,posted());}
    @Test void rejectedReceiptDoesNotPostAndCannotBeAllocatedAgain(){long p=group();dispatch(p);receive(body(p,"REJECT",3,"",false));Map<String,Object> d=decision(p);d.put("decision","REJECT");parcels.allocate("QM",21,p,event("REJECT"),d,returns);assertEquals(0,posted());assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",21,p,event("REJECT"),decision(p),returns));}
    @Test void incompleteAllocationRollsBackAllSources(){long p=group();dispatch(p);receive(body(p,"INCOMPLETE",3,"",false));Map<String,Object> d=decision(p);d.put("allocations",Arrays.asList(map("line_index",0,"task_id",task(1),"good_qty",2,"bad_qty",0)));assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",21,p,event("INCOMPLETE"),d,returns));assertEquals(0,posted());}
    @Test void callbackLineCannotBeReassignedToAnotherRefund(){long p=group();dispatch(p);receive(body(p,"LINE_SHORT",1,line(1),true));Map<String,Object> d=decision(p);d.put("allocations",Arrays.asList(map("line_index",0,"task_id",task(3),"good_qty",1,"bad_qty",0)));assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",23,p,event("LINE_SHORT"),d,returns));assertEquals(0,posted());}
    @Test void tenantAndRefundCannotAllocateAnotherParcelsGoods(){long p=group();dispatch(p);receive(body(p,"AUTH",3,"",false));assertThrows(IllegalArgumentException.class,()->parcels.allocate("OTHER",21,p,event("AUTH"),decision(p),returns));assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",999,p,event("AUTH"),decision(p),returns));}
    @Test void explicitOverReceiptReopensItsCompletedSourceWithoutBlockingOtherRefunds(){long p=group();dispatch(p);receive(body(p,"CLOSED_LINE",2,line(1),false));receive(body(p,"EXTRA_LINE",1,line(1),false));assertEquals(2,posted());assertEquals(1,id(returns.detail("QM",1).get("pending_review_count")));assertEquals(0,id(returns.detail("QM",2).get("pending_review_count")));}
    @Test void directDispatchCannotReuseCanceledSources(){long p=group();dispatch(p);shared.action("QM",1,"cancel",map("reason","stop","evidence","proof","confirmed_shared",true,"parcel_version",version(p)),returns);assertThrows(IllegalArgumentException.class,()->returns.prepare("QM",1,map("parcel_version",version(p))));assertEquals(1,creates.get());assertEquals(0,posted());}
    @Test void stoppedSharedDocumentRebuildsOnlyUnreceivedSources(){long p=group();dispatch(p);receive(body(p,"RECEIVED",2,line(1),false));String original=text(shared.document("QM",p).get("return_sn"));shared.action("QM",1,"cancel",map("reason","stop","evidence","proof","confirmed_shared",true,"parcel_version",version(p)),returns);shared.action("QM",1,"rebuild",map("reason","continue remaining","evidence","proof","confirmed_shared",true,"parcel_version",version(p)),returns);assertNotEquals(original,shared.document("QM",p).get("return_sn"));assertEquals(2,id(shared.document("QM",p).get("quantity")));assertEquals(2,creates.get());assertEquals(2,posted());}
    @Test void configuredPartialReceiptAutomaticallyAllocatesTwoOneZeroAndDeduplicates(){allocationMode="RULE";partialAllowed=true;uniformCost=true;long p=group();dispatch(p);String b=body(p,"PART_RULE",3,"",false);assertTrue(receive(b).contains("success"));assertEquals(3,posted());assertEquals(2,id(returns.detail("QM",1).get("posted_quantity")));assertEquals(1,id(returns.detail("QM",2).get("posted_quantity")));assertEquals(0,id(returns.detail("QM",3).get("posted_quantity")));assertTrue(receive(b).contains("success"));assertEquals(3,posted());String metadata=text(f.f.db.one("SELECT allocation_metadata FROM wms_refund_parcel_receipt WHERE id=?",event("PART_RULE")).get("allocation_metadata"));assertTrue(metadata.contains("RULE_PARTIAL"));assertTrue(metadata.contains("policy_revision"));receive(body(p,"LAST_RULE",1,"",true));assertEquals(4,posted());}
    @Test void partialRuleDoesNotMixOriginalCostsOrAcceptOverReceipt(){allocationMode="RULE";partialAllowed=true;long p=group();dispatch(p);receive(body(p,"COST",3,"",false));assertEquals(0,posted());assertTrue(text(f.f.db.one("SELECT allocation_metadata FROM wms_refund_parcel_receipt WHERE id=?",event("COST")).get("allocation_metadata")).contains("成本"));receive(body(p,"OVER_RULE",5,"",true));assertEquals(0,posted());}
    @Test void manualModeNeverAutomaticallyAllocatesEvenAnExactLine(){allocationMode="MANUAL";long p=group();dispatch(p);receive(body(p,"MANUAL_MODE",1,line(3),false));assertEquals(0,posted());}
    @Test void previewIsReadOnlyAndRejectsChangedPolicyVersion(){allocationMode="RULE";partialAllowed=false;uniformCost=true;long p=group();dispatch(p);receive(body(p,"PREVIEW",3,"",false));partialAllowed=true;Map<String,Object> preview=allocator.evaluate("QM",21,p,event("PREVIEW"),map("execute",false),parcels,returns);assertEquals("READY",preview.get("status"));assertEquals(0,posted());assertThrows(IllegalArgumentException.class,()->allocator.evaluate("QM",21,p,event("PREVIEW"),map("execute",true,"confirmed",true,"parcel_version",preview.get("parcel_version"),"policy_revision",2),parcels,returns));allocator.evaluate("QM",21,p,event("PREVIEW"),map("execute",true,"confirmed",true,"parcel_version",preview.get("parcel_version"),"policy_revision",3),parcels,returns);assertEquals(3,posted());}
    @Test void rulePriorityUsesRefundApplicationTimeAndNotMembershipOrder(){allocationMode="RULE";partialAllowed=true;uniformCost=true;long p=group();dispatch(p);Map<String,Object> context=allocationContext();for(Map<String,Object> row:(List<Map<String,Object>>)context.get("priorities"))if(id(row.get("plan_id"))==3)row.put("refund_created","2026-09-01 00:00:00");when(allocationOrders.context(anyString(),anyLong(),anyList(),anyString())).thenReturn(com.ruoyi.common.core.domain.R.ok(context));receive(body(p,"PRIORITY",1,"",false));assertEquals(1,id(returns.detail("QM",3).get("posted_quantity")));assertEquals(0,id(returns.detail("QM",1).get("posted_quantity")));}
    @Test void ruleCanPostReceivedGoodsWithoutClosingFinalShortage(){allocationMode="RULE";partialAllowed=true;uniformCost=true;long p=group();dispatch(p);receive(body(p,"FINAL_RULE",3,"",true));assertEquals(3,posted());assertEquals(0,id(returns.detail("QM",3).get("accepted_quantity")));assertNotEquals("COMPLETED",returns.detail("QM",3).get("receipt_state"));}
    @Test void unavailableOrderPolicyRetainsReceiptAndExistingScanRetries(){uniformCost=true;long p=group();dispatch(p);when(allocationOrders.context(anyString(),anyLong(),anyList(),anyString())).thenThrow(new IllegalStateException("offline"));receive(body(p,"RETRY_RULE",3,"",false));assertEquals(0,posted());allocationMode="RULE";partialAllowed=true;doAnswer(x->com.ruoyi.common.core.domain.R.ok(allocationContext())).when(allocationOrders).context(anyString(),anyLong(),anyList(),anyString());f.f.jdbc.update("UPDATE wms_refund_parcel_receipt SET auto_after=NOW() WHERE id=?",event("RETRY_RULE"));parcels.reconcileAutomatic("QM",returns);assertEquals(3,posted());}

}
